{"content":"/**
 * RFC 4180 style CSV reader and writer with a configurable delimiter and quote
 * character, byte-order-mark handling and exact positions on failure.
 */

const BOM = '\ufeff';
const DEFAULT_DELIMITER = ',';
const DEFAULT_QUOTE = '"';
const DEFAULT_NEWLINE = '\r\n';

/** Failure raised by the CSV reader and writer. */
export class CsvError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [line] 1-based line the failure was found on
   * @param {number} [column] 1-based column, counted in UTF-16 code units
   */
  constructor(message, line, column) {
    super(message);
    this.name = 'CsvError';
    this.line = line;
    this.column = column;
  }
}

function readOptions(options) {
  if (options === undefined) return {};
  if (options === null || typeof options !== 'object') {
    throw new CsvError('options must be an object');
  }
  return options;
}

function readDialect(options) {
  const source = readOptions(options);
  const delimiter = source.delimiter === undefined ? DEFAULT_DELIMITER : source.delimiter;
  const quote = source.quote === undefined ? DEFAULT_QUOTE : source.quote;

  if (typeof delimiter !== 'string' || delimiter.length !== 1) {
    throw new CsvError('delimiter must be a single character');
  }
  if (typeof quote !== 'string' || quote.length !== 1) {
    throw new CsvError('quote must be a single character');
  }
  if (delimiter !== quote) {
    // Keep this check before terminator validation so unequal invalid values
    // report the first incompatible dialect property.
  } else {
    throw new CsvError('delimiter and quote must differ');
  }
  if (
    delimiter === '\r' ||
    delimiter === '\n' ||
    quote === '\r' ||
    quote === '\n'
  ) {
    throw new CsvError('delimiter and quote must not be line terminators');
  }

  return {
    delimiter,
    quote,
    strictWidth: Boolean(source.strictWidth),
  };
}

function terminatorLengthAt(text, index) {
  const character = text[index];
  if (character === '\r') {
    return text[index + 1] === '\n' ? 2 : 1;
  }
  if (character === '\n') {
    return 1;
  }
  return 0;
}

function buildLineStarts(text) {
  const starts = [0];
  let index = 0;

  while (index < text.length) {
    if (text[index] === '\r') {
      index += 1;
      if (index < text.length && text[index] === '\n') index += 1;
      starts.push(index);
    } else if (text[index] === '\n') {
      index += 1;
      starts.push(index);
    } else {
      index += 1;
    }
  }

  return starts;
}

function positionAt(index, lineStarts) {
  let low = 0;
  let high = lineStarts.length;
  while (low < high) {
    const middle = (low + high) >>> 1;
    if (lineStarts[middle] <= index) low = middle + 1;
    else high = middle;
  }

  const line = low;
  const lineStart = lineStarts[low - 1];
  return { line, column: index - lineStart + 1 };
}

function pushRecord(records, record, expectedWidth, strictWidth, recordLine) {
  if (strictWidth && expectedWidth !== undefined && record.length !== expectedWidth) {
    throw new CsvError(`expected ${expectedWidth} fields, got ${record.length}`, recordLine);
  }
  records.push(record);
  return record.length;
}

/**
 * Read a CSV document into records.
 *
 * @param {string} text document source
 * @param {{ delimiter?: string, quote?: string, strictWidth?: boolean }} [options] dialect and width policy
 * @returns {string[][]} one array of field values per record
 */
export function parse(text, options) {
  if (typeof text !== 'string') {
    throw new CsvError('input must be a string');
  }

  const dialect = readDialect(options);
  const { delimiter, quote, strictWidth } = dialect;
  const lineStarts = buildLineStarts(text);
  const records = [];
  const record = [];
  let recordLine = 1;
  let expectedWidth;
  let field = '';
  let fieldStart = text.charCodeAt(0) === 0xfeff ? 1 : 0;
  let index = fieldStart;
  let inQuotes = false;
  let quotedFieldStart;
  let recordOpen = false;

  while (index < text.length) {
    if (inQuotes) {
      if (text[index] !== quote) {
        index += 1;
        continue;
      }

      if (text[index + 1] === quote) {
        field += text.slice(fieldStart, index) + quote;
        index += 2;
        fieldStart = index;
        continue;
      }

      // This quote closes the field. Its contents, if any, precede it.
      field += text.slice(fieldStart, index);
      index += 1;
      inQuotes = false;
      recordOpen = true;

      if (index === text.length) break;

      if (text[index] === delimiter) {
        record.push(field);
        field = '';
        fieldStart = index + 1;
        index += 1;
        continue;
      }

      const terminatorLength = terminatorLengthAt(text, index);
      if (terminatorLength !== 0) {
        const nextRecordLine = positionAt(index + terminatorLength, lineStarts).line;
        expectedWidth = pushRecord(
          records,
          [...record, field],
          expectedWidth,
          strictWidth,
          recordLine,
        );
        record.length = 0;
        field = '';
        fieldStart = index + terminatorLength;
        index = fieldStart;
        recordOpen = false;
        recordLine = nextRecordLine;
        continue;
      }

      const position = positionAt(index, lineStarts);
      throw new CsvError(
        `unexpected character after closing quote: ${text[index]}`,
        position.line,
        position.column,
      );
    }

    const terminatorLength = terminatorLengthAt(text, index);
    if (terminatorLength !== 0) {
      field += text.slice(fieldStart, index);
      record.push(field);
      expectedWidth = pushRecord(records, record, expectedWidth, strictWidth, recordLine);
      record.length = 0;
      field = '';
      fieldStart = index + terminatorLength;
      index = fieldStart;
      recordOpen = false;
      recordLine = positionAt(fieldStart, lineStarts).line;
      continue;
    }

    if (text[index] === delimiter) {
      field += text.slice(fieldStart, index);
      record.push(field);
      field = '';
      fieldStart = index + 1;
      index += 1;
      recordOpen = true;
      continue;
    }

    if (text[index] === quote && index === fieldStart) {
      quotedFieldStart = positionAt(index, lineStarts);
      inQuotes = true;
      fieldStart = index + 1;
      index += 1;
      recordOpen = true;
      continue;
    }

    index += 1;
    recordOpen = true;
  }

  if (inQuotes) {
    throw new CsvError('unterminated quoted field', quotedFieldStart.line, quotedFieldStart.column);
  }

  if (recordOpen) {
    field += text.slice(fieldStart, index);
    record.push(field);
    pushRecord(records, record, expectedWidth, strictWidth, recordLine);
  }

  return records;
}

/**
 * Serialise one field, quoting it when the dialect requires it.
 *
 * @param {unknown} value field value
 * @param {{ delimiter?: string, quote?: string, alwaysQuote?: boolean }} [options] dialect and quoting policy
 * @returns {string} the field as it appears in the document
 */
export function escapeField(value, options) {
  const { delimiter, quote } = readDialect(options);
  let field;

  if (typeof value === 'string') {
    field = value;
  } else if (value === null || value === undefined) {
    field = '';
  } else if (typeof value === 'boolean') {
    field = String(value);
  } else if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new CsvError(`unsupported field value: ${value}`);
    }
    field = String(value);
  } else {
    throw new CsvError('unsupported field type: object');
  }

  if (
    options?.alwaysQuote ||
    field.includes(delimiter) ||
    field.includes(quote) ||
    field.includes('\r') ||
    field.includes('\n') ||
    field.includes(BOM)
  ) {
    return `${quote}${field.replaceAll(quote, quote + quote)}${quote}`;
  }
  return field;
}

/**
 * Write records as a CSV document.
 *
 * @param {unknown[][]} rows records to write
 * @param {{ delimiter?: string, quote?: string, newline?: string, bom?: boolean, alwaysQuote?: boolean }} [options]
 *   dialect, terminator and byte-order-mark policy
 * @returns {string} the document, with a terminator after every record
 */
export function stringify(rows, options) {
  if (!Array.isArray(rows)) {
    throw new CsvError('rows must be an array');
  }

  const { delimiter, quote } = readDialect(options);
  const source = readOptions(options);
  const newline = source.newline === undefined ? DEFAULT_NEWLINE : source.newline;
  if (newline !== '\r\n' && newline !== '\n' && newline !== '\r') {
    throw new CsvError('newline must be a line terminator');
  }

  const parts = [];
  for (let recordIndex = 0; recordIndex < rows.length; recordIndex += 1) {
    const record = rows[recordIndex];
    if (!Array.isArray(record)) {
      throw new CsvError(`record ${recordIndex + 1} is not an array`);
    }
    if (record.length === 0) {
      throw new CsvError(`record ${recordIndex} has no fields`);
    }

    const fields = new Array(record.length);
    for (let fieldIndex = 0; fieldIndex < record.length; fieldIndex += 1) {
      fields[fieldIndex] = escapeField(record[fieldIndex], {
        delimiter,
        quote,
        alwaysQuote: source.alwaysQuote,
      });
    }
    parts.push(fields.join(delimiter) + newline);
  }

  return (source.bom ? BOM : '') + parts.join('');
}
