    return { type: 'globstar' };
  }

  const tokens = [];
  let position = 0;
  let literal = '';

  const flushLiteral = () => {
    if (literal !== '') {
      tokens.push({ type: 'literal', value: literal });
      literal = '';
    }
  };
  const appendLiteral = (character) => {
    literal += character;
  };

  while (position < source.length) {
    const { codePoint, character, width } = readCodePoint(source, position);

    if (codePoint === STAR) {
