        throw new GlobError('path separator in character class', escapedIndex);
      }
      const escaped = readCodePoint(source, escapedIndex);
      atoms.push({ codePoint: escaped.codePoint, index: escapedIndex });
      position = escapedIndex + escaped.width;
      continue;
    }

    if (source[position] === ']') {
      if (atoms.length === 0) {
        atoms.push({ codePoint: CLOSE_BRACKET, index: position });
        position += 1;
        continue;
      }
      return {
        end: position + 1,
        token: makeCharacterClass(atoms, negated),
      };
    }

    const atom = readCodePoint(source, position);
    atoms.push({ codePoint: atom.codePoint, index: position });
    position += atom.width;
  }

  throw new GlobError('unterminated character class', openIndex);
}

function makeCharacterClass(atoms, negated) {
  const members = [];

  for (let index = 0; index < atoms.length; ) {
    if (
      index + 2 < atoms.length &&
      atoms[index + 1].codePoint === DASH
    ) {
      const first = atoms[index];
      const last = atoms[index + 2];
      members.push({
        type: 'range',
        first: Math.min(first.codePoint, last.codePoint),
        last: Math.max(first.codePoint, last.codePoint),
      });
      index += 3;
    } else {
      members.push({ type: 'literal', codePoint: atoms[index].codePoint });
      index += 1;
    }
  }

  return { negated, members };
}

function createSegmentMatcher(tokens, nocase) {
  return function matchSegment(text) {
    const characters = Array.from(text);
    const memo = Array.from({ length: tokens.length + 1 }, () => new Array(characters.length + 1));

    function matchFrom(tokenIndex, characterIndex) {
      if (memo[tokenIndex][characterIndex] !== undefined) {
        return memo[tokenIndex][characterIndex];
      }

      let result;
      if (tokenIndex === tokens.length) {
        result = characterIndex === characters.length;
      } else {
        const token = tokens[tokenIndex];
        if (token.type === 'literal') {
          const literal = Array.from(token.value);
          result =
            literal.length <= characters.length - characterIndex &&
            literal.every(
              (character, offset) =>
                equivalent(character, characters[characterIndex + offset], nocase),
            ) &&
            matchFrom(tokenIndex + 1, characterIndex + literal.length);
        } else if (token.type === 'star') {
          result =
            matchFrom(tokenIndex + 1, characterIndex) ||
            (characterIndex < characters.length &&
              characters[characterIndex].codePointAt(0) !== PATH_SEPARATOR &&
              matchFrom(tokenIndex, characterIndex + 1));
        } else if (token.type === 'question') {
          result =
            characterIndex < characters.length &&
            characters[characterIndex].codePointAt(0) !== PATH_SEPARATOR &&
            matchFrom(tokenIndex + 1, characterIndex + 1);
        } else {
          result =
            characterIndex < characters.length &&
            characterInClass(characters[characterIndex], token, nocase) &&
            matchFrom(tokenIndex + 1, characterIndex + 1);
        }
      }

      memo[tokenIndex][characterIndex] = result;
      return result;
    }

    return matchFrom(0, 0);
  };
}

function characterInClass(character, token, nocase) {
  const codePoint = character.codePointAt(0);
  if (codePoint === PATH_SEPARATOR) {
    return false;
  }

  let matched = false;
  for (const member of token.members) {
    if (member.type === 'range') {
      matched = codePointInRange(codePoint, member, nocase);
    } else if (equivalent(character, String.fromCodePoint(member.codePoint), nocase)) {
      matched = true;
    }
    if (matched) {
      break;
    }
  }

  return token.negated ? !matched : matched;
}

function codePointInRange(codePoint, range, nocase) {
  if (!nocase) {
    return codePoint >= range.first && codePoint <= range.last;
  }

  const character = String.fromCodePoint(codePoint).toLowerCase();
  const first = String.fromCodePoint(range.first).toLowerCase();
  const last = String.fromCodePoint(range.last).toLowerCase();
  if (character.length !== 1 || first.length !== 1 || last.length !== 1) {
    return character === first || character === last;
  }

  const folded = character.codePointAt(0);
  return folded >= first.codePointAt(0) && folded <= last.codePointAt(0);
}

function equivalent(left, right, nocase) {
  if (left === right) {
    return true;
  }
  if (!nocase) {
    return false;
  }
  return (
    left.toLowerCase() === right.toLowerCase() ||
    left.toUpperCase() === right.toUpperCase()
  );
}

function readCodePoint(source, position) {
  const codePoint = source.codePointAt(position);
  const character = String.fromCodePoint(codePoint);
  return {
    codePoint,
    character,
    width: codePoint > 0xffff ? 2 : 1,
  };
}

function matchSegments(patternSegments, pathSegments, dot) {
  const memo = Array.from(
    { length: patternSegments.length + 1 },
    () => new Array(pathSegments.length + 1),
  );

  function matchFrom(patternIndex, pathIndex) {
    if (memo[patternIndex][pathIndex] !== undefined) {
      return memo[patternIndex][pathIndex];
    }

    let result;
    if (patternIndex === patternSegments.length) {
      result = pathIndex === pathSegments.length;
    } else {
      const segment = patternSegments[patternIndex];
      if (segment.type === 'globstar') {
        result = matchFrom(patternIndex + 1, pathIndex);
        for (
          let nextPathIndex = pathIndex;
          !result &&
          nextPathIndex < pathSegments.length &&
          (dot || pathSegments[nextPathIndex].charCodeAt(0) !== DOT);
          nextPathIndex += 1
        ) {
          result = matchFrom(patternIndex + 1, nextPathIndex + 1);
        }
      } else {
        result =
          pathIndex < pathSegments.length &&
          segment.matches(pathSegments[pathIndex]) &&
          matchFrom(patternIndex + 1, pathIndex + 1);
      }
    }

    memo[patternIndex][pathIndex] = result;
    return result;
  }

  return matchFrom(0, 0);
}
