 * Fixed-width plain-text tables: display width, wrapping, padding and layout.
 */

/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

/**
 * Classify a single code point's display width.
 * @param {number} cp Code point.
 * @returns {number} 0, 1 or 2.
 */
function codePointWidth(cp) {
  if (cp < 0x0020 || cp === 0x007f) return 0;
  if ((cp >= 0x0300 && cp <= 0x036f) || cp === 0x200b || cp === 0x200c || cp === 0x200d || cp === 0xfeff) {
    return 0;
  }
  // Two-column ranges (inclusive).
  const wide = [
    [0x1100, 0x115f],
    [0x2e80, 0x303e],
    [0x3041, 0x33ff],
    [0x3400, 0x4dbf],
    [0x4e00, 0x9fff],
    [0xa000, 0xa4cf],
    [0xac00, 0xd7a3],
    [0xf900, 0xfaff],
    [0xfe10, 0xfe19],
    [0xfe30, 0xfe6f],
    [0xff00, 0xff60],
    [0xffe0, 0xffe6],
    [0x1f300, 0x1f64f],
    [0x1f900, 0x1f9ff],
    [0x20000, 0x2fffd],
    [0x30000, 0x3fffd],
  ];
  for (const [lo, hi] of wide) {
    if (cp >= lo && cp <= hi) return 2;
  }
  return 1;
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  let width = 0;
  for (const cp of text) {
    const code = cp.codePointAt(0);
    width += codePointWidth(code);
  }
  return width;
}

/**
 * Break a single word (no spaces) into chunks of at most `width` columns.
 * A wide character that would straddle the boundary starts the next chunk.
 * Throws UNWRAPPABLE if any single character is wider than the column.
 *
 * @param {string} word Word with no spaces.
 * @param {number} width Column width.
 * @returns {string[]} Chunks.
 */
function breakWord(word, width) {
  const chunks = [];
  let current = '';
  let currentWidth = 0;
  for (const cp of word) {
    const code = cp.codePointAt(0);
    const w = codePointWidth(code);
    if (w > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
    }
    if (currentWidth + w > width) {
      chunks.push(current);
      current = cp;
      currentWidth = w;
    } else {
      current += cp;
      currentWidth += w;
    }
  }
  if (current !== '') {
    chunks.push(current);
  }
  return chunks;
}

/**
 * Wrap cell text to a column width.
 *
 * @param {string} text Cell text; explicit newlines start a new line.
 * @param {number} width Column width in display columns.
 * @returns {string[]} Wrapped lines, at least one.
 */
export function wrapCell(text, width) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }

  const pieces = text.split('\n');
  const lines = [];
  for (const piece of pieces) {
    // Collapse runs of spaces and split into words; leading/trailing spaces vanish.
    const words = piece.split(/ +/).filter((w) => w !== '');
    lines.push(...packWords(words, width));
  }
  if (lines.length === 0) {
    return [''];
  }
  return lines;
}

/**
 * Pack a list of words into lines of at most `width` columns.
 * Each word is first hard-broken into chunks that fit the column, then chunks
 * are packed greedily with a single space between neighbours.
 *
 * @param {string[]} words Words (already split, no surrounding spaces).
 * @param {number} width Column width.
 * @returns {string[]} Lines.
 */
function packWords(words, width) {
  if (words.length === 0) {
    return [''];
  }
  // Pre-break each word into chunks that individually fit the column.
  const allChunks = [];
  for (const word of words) {
    allChunks.push(...breakWord(word, width));
  }

  const lines = [];
  let line = '';
  let lineWidth = 0;
  for (const chunk of allChunks) {
    const chunkWidth = stringWidth(chunk);
    if (lineWidth === 0) {
      // First chunk on a line: it always fits (breakWord guarantees ≤ width,
      // or throws if a single char is too wide).
      line = chunk;
      lineWidth = chunkWidth;
    } else if (lineWidth + 1 + chunkWidth <= width) {
      line += ' ' + chunk;
      lineWidth += 1 + chunkWidth;
    } else {
      lines.push(line);
      line = chunk;
      lineWidth = chunkWidth;
    }
  }
  if (line !== '') {
    lines.push(line);
  }
  // packWords is only called with words.length > 0, so lines is never empty.
  return lines;
}

