 * Pad a single line to an exact display width.
 *
 * @param {string} text Line that already fits.
 * @param {number} width Target column width.
 * @param {'left'|'right'|'center'} [align] Alignment, left by default.
 * @returns {string} Padded line.
 */
export function padCell(text, width, align = 'left') {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }
  if (align !== 'left' && align !== 'right' && align !== 'center') {
    throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
  }

  const contentWidth = stringWidth(text);
  if (contentWidth > width) {
    throw new TableError('CELL_TOO_WIDE', 'content is wider than the column');
  }

  const pad = width - contentWidth;
  if (align === 'left') {
    return text + ' '.repeat(pad);
  } else if (align === 'right') {
    return ' '.repeat(pad) + text;
  } else {
    // center: smaller half on the left.
    const left = Math.floor(pad / 2);
    const right = pad - left;
    return ' '.repeat(left) + text + ' '.repeat(right);
  }
}

/**
 * Render rows as a fixed-width table.
 *
 * @param {string[][]} rows Rows of cells.
 * @param {{widths: number[], align?: string[], header?: boolean}} options Layout options.
 * @returns {string} Table text without a trailing newline.
 */
export function formatTable(rows, options) {
  if (options === null || typeof options !== 'object' || Array.isArray(options)) {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }
  const widths = options.widths;
  if (!Array.isArray(widths) || widths.length === 0 || !widths.every((w) => Number.isInteger(w) && w >= 1)) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }
  const numCols = widths.length;

  let align = options.align;
  if (align !== undefined) {
    if (!Array.isArray(align) || align.length !== numCols) {
      throw new TableError('BAD_ALIGN', `align must have ${numCols} entries`);
    }
    for (const a of align) {
      if (a !== 'left' && a !== 'right' && a !== 'center') {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${a}`);
      }
    }
  } else {
    align = widths.map(() => 'left');
  }

  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }

  for (let i = 0; i < rows.length; i++) {
    const row = rows[i];
    const cells = Array.isArray(row) ? row : [];
    if (cells.length !== numCols) {
      throw new TableError('BAD_ROW_LENGTH', `row ${i} has ${cells.length} cells, expected ${numCols}`);
    }
    for (let j = 0; j < cells.length; j++) {
      if (typeof cells[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }

  if (rows.length === 0) {
    return '';
  }

  // Wrap each cell.
  const wrappedRows = rows.map((row) => row.map((cell, col) => wrapCell(cell, widths[col])));

  // Determine line count per row (tallest cell).
  const lineCounts = wrappedRows.map((row) => Math.max(...row.map((lines) => lines.length)));

  const allLines = [];
  let rowIndex = 0;
  for (let r = 0; r < wrappedRows.length; r++) {
    const wrappedRow = wrappedRows[r];
    const lineCount = lineCounts[r];
    for (let line = 0; line < lineCount; line++) {
      const cells = wrappedRow.map((cellLines, col) => {
        const text = cellLines[line] !== undefined ? cellLines[line] : '';
        return padCell(text, widths[col], align[col]);
      });
      allLines.push(cells.join(' | '));
    }
    // Header rule follows the first row.
    if (options.header && r === 0) {
      const rule = widths.map((w) => '-'.repeat(w)).join('-+-');
      allLines.push(rule);
    }
    rowIndex++;
    void rowIndex;
  }

  return allLines.join('\n');
}
"}

