  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }

  const pieces = text.split('\n');
  const lines = [];
  for (const piece of pieces) {
    // Collapse runs of spaces and split into words; leading/trailing spaces vanish.
    const words = piece.split(/ +/).filter((w) => w !== '');
    lines.push(...packWords(words, width));
  }
  if (lines.length === 0) {
    return [''];
  }
  return lines;
