          lines.push(line);
          line = chunk;
          lineWidth = chunkWidth;
          lineHasContent = true;
        }
      } else if (lineWidth + chunkWidth <= width) {
        line += chunk;
        lineWidth += chunkWidth;
      } else {
        lines.push(line);
