 * Stable multi-key sorting with per-key direction and null placement.
 */

/**
 * Total order over sortable values: absent values first, then numbers,
 * strings, and booleans.
 * @param {unknown} a First value.
 * @param {unknown} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
export function compareValues(a, b) {
  // Check for absent values
  const aAbsent = a === null || a === undefined || (typeof a === 'number' && Number.isNaN(a));
  const bAbsent = b === null || b === undefined || (typeof b === 'number' && Number.isNaN(b));

  if (aAbsent && bAbsent) return 0;
  if (aAbsent) return -1;
  if (bAbsent) return 1;

  // Both values are present, check types
  const typeA = typeof a;
  const typeB = typeof b;

  // Handle unsupported types
  const supportedTypes = ['number', 'string', 'boolean'];
  if (!supportedTypes.includes(typeA)) {
    throw new TypeError(`unsupported value type: ${typeA}`);
  }
  if (!supportedTypes.includes(typeB)) {
    throw new TypeError(`unsupported value type: ${typeB}`);
  }

  // Order by type rank: number (0), string (1), boolean (2)
  const typeRank = { number: 0, string: 1, boolean: 2 };
  const rankA = typeRank[typeA];
  const rankB = typeRank[typeB];

  if (rankA !== rankB) return rankA - rankB;

  // Same type, compare values
  switch (typeA) {
    case 'number':
      // Handle -0 and 0 as equal
      if (a === 0 && b === 0) return 0;
      return a === b ? 0 : a < b ? -1 : 1;
    case 'string':
      // Compare by Unicode code point
      const left = [...a].map(c => c.codePointAt(0));
      const right = [...b].map(c => c.codePointAt(0));
      for (let i = 0; i < Math.min(left.length, right.length); i++) {
        if (left[i] !== right[i]) return left[i] - right[i];
      }
      return left.length - right.length;
    case 'boolean':
      return (a ? 1 : 0) - (b ? 1 : 0);
    default:
      // This should never happen due to the type check above
      throw new TypeError(`unsupported value type: ${typeA}`);
  }
}

/**
 * Builds a comparator over rows from a list of key specs.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {(a: unknown, b: unknown) => number} Comparator returning negative, zero, or positive.
 */
export function comparator(specs) {
  // Validate specs
  if (!Array.isArray(specs)) {
    throw new TypeError('at least one key spec is required');
  }
  if (specs.length === 0) {
    throw new TypeError('at least one key spec is required');
  }

  for (const spec of specs) {
    if (typeof spec !== 'object' || spec === null) {
      throw new TypeError('key spec must be an object');
    }
    if (typeof spec.key !== 'string' && typeof spec.key !== 'function') {
      throw new TypeError('key must be a string path or a function');
    }
    if (spec.direction !== undefined && spec.direction !== 'asc' && spec.direction !== 'desc') {
      throw new RangeError(`unknown direction: ${JSON.stringify(spec.direction)}`);
    }
    if (spec.nulls !== undefined && spec.nulls !== 'first' && spec.nulls !== 'last') {
      throw new RangeError(`unknown null placement: ${JSON.stringify(spec.nulls)}`);
    }
  }

  return (a, b) => {
    for (const spec of specs) {
      // Get values for this key
      let left, right;
      if (typeof spec.key === 'function') {
        left = spec.key(a);
        right = spec.key(b);
      } else {
        // Handle dot-separated property path
        left = spec.key.split('.').reduce((v, p) => (v == null ? undefined : v[p]), a);
        right = spec.key.split('.').reduce((v, p) => (v == null ? undefined : v[p]), b);
      }

      // Handle absent values
      const leftAbsent = left === null || left === undefined || (typeof left === 'number' && Number.isNaN(left));
      const rightAbsent = right === null || right === undefined || (typeof right === 'number' && Number.isNaN(right));

      if (leftAbsent || rightAbsent) {
        if (leftAbsent && rightAbsent) continue;
        const nullsFirst = (spec.nulls ?? 'last') === 'first';
        const absentValue = leftAbsent ? -1 : 1;
        return absentValue * (nullsFirst ? 1 : -1);
      }

      // Compare present values
      let order;
      try {
        order = compareValues(left, right);
      } catch (error) {
        // Re-throw TypeError from compareValues
        throw error;
      }

      if (order !== 0) {
        const direction = spec.direction ?? 'asc';
        return order * (direction === 'asc' ? 1 : -1);
      }
    }
    return 0;
  };
}

/**
 * Returns the permutation of row indices that sorts the rows.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {number[]} Indices of `rows` in sorted order, stable for ties.
 */
export function sortIndices(rows, specs) {
  // Validate rows
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  const compare = comparator(specs);
  const indices = rows.map((_, index) => index);

  // Use insertion sort for stability
  for (let i = 1; i < indices.length; i++) {
    const currentIndex = indices[i];
    let j = i - 1;

    while (j >= 0 && compare(rows[indices[j]], rows[currentIndex]) > 0) {
      indices[j + 1] = indices[j];
      j--;
    }
    indices[j + 1] = currentIndex;
  }

  return indices;
}

/**
 * Sorts rows without mutating the input.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {unknown[]} New array holding the rows in sorted order.
 */
export function sortBy(rows, specs) {
  // Validate rows
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }

  // Get sorted indices and map to rows
  const indices = sortIndices(rows, specs);
  return indices.map(index => rows[index]);
}"}

