{"file_path":"src/sortBy.js","content":"/**
 * Stable multi-key sorting with per-key direction and null placement.
 */

const VALUE_RANK = {
  number: 0,
  string: 1,
  boolean: 2,
};

/**
 * Return a JSON representation suitable for an error message.
 * @param {unknown} value Value to represent.
 * @returns {string} JSON representation, with undefined represented explicitly.
 */
function formatJsonValue(value) {
  const serialized = JSON.stringify(value);
  return serialized === undefined ? 'undefined' : serialized;
}

/**
 * Validate and classify one value used by compareValues.
 * @param {unknown} value Value to validate.
 * @returns {void}
 */
function validateValue(value) {
  const type = typeof value;
  if (value !== null && value !== undefined && !(type === 'number' && Number.isNaN(value))
      && VALUE_RANK[type] === undefined) {
    throw new TypeError(`unsupported value type: ${type}`);
  }
}

/**
 * Total order over sortable values: absent values first, then numbers,
 * strings, and booleans.
 * @param {unknown} a First value.
 * @param {unknown} b Second value.
 * @returns {number} Negative, zero, or positive.
 */
export function compareValues(a, b) {
  validateValue(a);
  validateValue(b);

  const aAbsent = a === null || a === undefined || (typeof a === 'number' && Number.isNaN(a));
  const bAbsent = b === null || b === undefined || (typeof b === 'number' && Number.isNaN(b));
  if (aAbsent || bAbsent) {
    if (aAbsent && bAbsent) return 0;
    return aAbsent ? -1 : 1;
  }

  const aType = typeof a;
  const bType = typeof b;
  if (aType !== bType) return VALUE_RANK[aType] - VALUE_RANK[bType];

  if (aType === 'number') {
    if (a === b) return 0;
    return a < b ? -1 : 1;
  }

  if (aType === 'string') {
    const left = Array.from(a);
    const right = Array.from(b);
    const length = Math.min(left.length, right.length);
    for (let index = 0; index < length; index += 1) {
      const leftCodePoint = left[index].codePointAt(0);
      const rightCodePoint = right[index].codePointAt(0);
      if (leftCodePoint !== rightCodePoint) return leftCodePoint - rightCodePoint;
    }
    return left.length - right.length;
  }

  return (a ? 1 : 0) - (b ? 1 : 0);
}

/**
 * Validate a key spec and return its normalized form.
 * @param {unknown} spec Candidate key spec.
 * @returns {{key: string|function, direction: 'asc'|'desc', nulls: 'first'|'last'}}
 */
function normalizeSpec(spec) {
  if (typeof spec !== 'object' || spec === null) {
    throw new TypeError('key spec must be an object');
  }

  const { key, direction, nulls } = spec;
  if (typeof key !== 'string' && typeof key !== 'function') {
    throw new TypeError('key must be a string path or a function');
  }

  const normalizedDirection = direction ?? 'asc';
  if (normalizedDirection !== 'asc' && normalizedDirection !== 'desc') {
    throw new RangeError(`unknown direction: ${formatJsonValue(direction)}`);
  }

  const normalizedNulls = nulls ?? 'last';
  if (normalizedNulls !== 'first' && normalizedNulls !== 'last') {
    throw new RangeError(`unknown null placement: ${formatJsonValue(nulls)}`);
  }

  return {
    key,
    direction: normalizedDirection,
    nulls: normalizedNulls,
  };
}

/**
 * Validate the row and spec arguments shared by the sorting entry points.
 * @param {unknown} rows Candidate rows.
 * @param {unknown} specs Candidate key specs.
 * @returns {Array<{key: string|function, direction: 'asc'|'desc', nulls: 'first'|'last'}>}
 */
function validateArguments(rows, specs) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  if (!Array.isArray(specs) || specs.length === 0) {
    throw new TypeError('at least one key spec is required');
  }
  return specs.map(normalizeSpec);
}

/**
 * Read a key from a row using a function or a dot-separated path.
 * @param {unknown} row Row to read.
 * @param {string|function} key Key accessor.
 * @returns {unknown} Key value.
 */
function readKey(row, key) {
  if (typeof key === 'function') return key(row);

  const parts = key.split('.');
  let value = row;
  for (const part of parts) {
    if (value === null || value === undefined) return undefined;
    value = value[part];
  }
  return value;
}

/**
 * Builds a comparator over rows from a list of key specs.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {(a: unknown, b: unknown) => number} Comparator returning negative, zero, or positive.
 */
export function comparator(specs) {
  if (!Array.isArray(specs) || specs.length === 0) {
    throw new TypeError('at least one key spec is required');
  }
  const normalizedSpecs = specs.map(normalizeSpec);

  return (a, b) => {
    for (const spec of normalizedSpecs) {
      const left = readKey(a, spec.key);
      const right = readKey(b, spec.key);
      const leftAbsent = left === null || left === undefined
        || (typeof left === 'number' && Number.isNaN(left));
      const rightAbsent = right === null || right === undefined
        || (typeof right === 'number' && Number.isNaN(right));

      if (leftAbsent || rightAbsent) {
        if (leftAbsent && rightAbsent) continue;
        const nullsFirst = spec.nulls === 'first';
        return (leftAbsent ? -1 : 1) * (nullsFirst ? 1 : -1);
      }

      const order = compareValues(left, right);
      if (order !== 0) return spec.direction === 'desc' ? -order : order;
    }
    return 0;
  };
}

/**
 * Returns the permutation of row indices that sorts the rows.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {number[]} Indices of `rows` in sorted order, stable for ties.
 */
export function sortIndices(rows, specs) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  const compare = comparator(specs);
  const indices = Array.from({ length: rows.length }, (_, index) => index);
  indices.sort((leftIndex, rightIndex) => {
    const order = compare(rows[leftIndex], rows[rightIndex]);
    return order || leftIndex - rightIndex;
  });
  return indices;
}

/**
 * Sorts rows without mutating the input.
 * @param {unknown} rows Rows to order.
 * @param {unknown} specs Key specs, applied in order.
 * @returns {unknown[]} New array holding the rows in sorted order.
 */
export function sortBy(rows, specs) {
  if (!Array.isArray(rows)) {
    throw new TypeError('rows must be an array');
  }
  return sortIndices(rows, specs).map((index) => rows[index]);
}
