/** Error raised for malformed paths and impossible requests. */
export class PathError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'PathError';
    this.code = code;
  }
}

/**
 * Report whether a path starts at the root.
 *
 * @param {string} path Path to inspect.
 * @returns {boolean} True for a rooted path.
 */
export function isAbsolute(path) {
  // Check argument type
  if (typeof path !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  // Check for NUL byte
  if (path.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  // Check if path starts with slash
  return path.startsWith('/');
}

/**
 * Collapse `.`, `..`, repeated slashes and trailing slashes.
 *
 * @param {string} path Path to normalize.
 * @returns {string} Normalized path.
 */
export function normalize(path) {
  // Check argument type
  if (typeof path !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  // Check for NUL byte
  if (path.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  // Check for empty path
  if (path === '') {
    throw new PathError('EMPTY_PATH', 'path must not be empty');
  }

  const isAbsolutePath = path.startsWith('/');
  const segments = path.split('/').filter(segment => segment !== '' && segment !== '.');
  const result = [];

  for (const segment of segments) {
    if (segment === '..') {
      if (result.length > 0) {
        result.pop();
      } else if (!isAbsolutePath) {
        // On relative paths, keep leading ..
        result.push('..');
      } else {
        // On absolute paths, escaping root
        throw new PathError('ESCAPE', `path escapes root: ${path}`);
      }
    } else {
      result.push(segment);
    }
  }

  if (isAbsolutePath) {
    return '/' + result.join('/') || '/';
  } else {
    return result.length > 0 ? result.join('/') : '.';
  }
}

/**
 * Join segments and normalize the result.
 *
 * @param {...string} segments One or more path segments.
 * @returns {string} Normalized joined path.
 */
export function join(...segments) {
  // Check for at least one segment
  if (segments.length === 0) {
    throw new PathError('NO_SEGMENTS', 'join requires at least one segment');
  }

  // Check each segment
  for (let i = 0; i < segments.length; i++) {
    const segment = segments[i];

    // Check argument type
    if (typeof segment !== 'string') {
      throw new PathError('NOT_A_STRING', 'path must be a string');
    }

    // Check for NUL byte
    if (segment.includes('\u0000')) {
      throw new PathError('NUL_BYTE', 'path contains a NUL byte');
    }

    // Check for empty segment
    if (segment === '') {
      throw new PathError('EMPTY_SEGMENT', `segment ${i} must not be empty`);
    }

    // Check if segment after first is absolute
    if (i > 0 && segment.startsWith('/')) {
      throw new PathError('ABSOLUTE_SEGMENT', `segment ${i} must be relative`);
    }
  }

  // Join segments with single slashes and normalize
  const joined = segments.join('/');
  return normalize(joined);
}

/**
 * Path from one absolute location to another.
 *
 * @param {string} from Absolute starting path.
 * @param {string} to Absolute destination path.
 * @returns {string} Relative path, empty when the two are the same.
 */
export function relative(from, to) {
  // Check argument types
  if (typeof from !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  if (typeof to !== 'string') {
    throw new PathError('NOT_A_STRING', 'path must be a string');
  }

  // Check for NUL bytes
  if (from.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  if (to.includes('\u0000')) {
    throw new PathError('NUL_BYTE', 'path contains a NUL byte');
  }

  // Check if both paths are absolute
  if (!from.startsWith('/')) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }

  if (!to.startsWith('/')) {
    throw new PathError('NOT_ABSOLUTE', 'both paths must be absolute');
  }

  // Normalize both paths (this may throw ESCAPE)
  const fromNorm = normalize(from);
  const toNorm = normalize(to);

  // Split into segments
  const fromSegments = fromNorm === '/' ? [] : fromNorm.slice(1).split('/');
  const toSegments = toNorm === '/' ? [] : toNorm.slice(1).split('/');

  // Find common prefix
  let commonLength = 0;
  const minLength = Math.min(fromSegments.length, toSegments.length);

  for (let i = 0; i < minLength; i++) {
    if (fromSegments[i] === toSegments[i]) {
      commonLength++;
    } else {
      break;
    }
  }

  // Build relative path
  const upSteps = fromSegments.length - commonLength;
  const downSteps = toSegments.slice(commonLength);

  const result = [];
  for (let i = 0; i < upSteps; i++) {
    result.push('..');
  }
  result.push(...downSteps);

  return result.join('/') || '';
}"}

