  if (path === '') {
    throw new PathError('EMPTY_PATH', 'path must not be empty');
  }

  const rooted = path.startsWith('/');
  const segments = [];

  for (const segment of path.split('/')) {
    if (segment === '' || segment === '.') {
      continue;
    }

    if (segment === '..') {
      if (segments.length > 0) {
        segments.pop();
      } else if (rooted) {
        throw new PathError('ESCAPE', `path escapes root: ${path}`);
      } else {
