export class PathError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'PathError';
    this.code = code;
  }
}

/**
 * Validate all path arguments before any operation is performed.
 *
 * @param {unknown[]} values Values to validate.
 */
function validateArguments(values) {
  for (const value of values) {
    if (typeof value !== 'string') {
      throw new PathError('NOT_A_STRING', 'path must be a string');
    }
    if (value.includes('\0')) {
      throw new PathError('NUL_BYTE', 'path contains a NUL byte');
    }
  }
}

/**
 * Normalize one already validated path.
 *
 * @param {string} path Path to normalize.
 * @returns {string} Normalized path.
 */
function normalizeValidated(path) {
  if (path === '') {
    throw new PathError('EMPTY_PATH', 'path must not be empty');
  }

  const rooted = path.startsWith('/');
  const segments = [];

  for (const segment of path.split('/')) {
    if (segment === '' || segment === '.') {
      continue;
    }

    if (segment === '..') {
      if (segments.length > 0) {
