{"file_path":"src/intervals.js","content":"/**
 * Set algebra over half-open integer intervals `[start, end)`.
 */

/**
 * Validates that a value is a safe integer.
 * @param {unknown} value - The value to validate.
 * @throws {TypeError} If the value is not a safe integer.
 */
function assertSafeInteger(value) {
  if (!Number.isSafeInteger(value)) {
    throw new TypeError('interval bounds must be safe integers');
  }
}

/**
 * Validates an interval list according to the specification.
 * @param {unknown} intervals - The interval list to validate.
 * @throws {TypeError} If the input is not an array or contains invalid intervals.
 * @throws {RangeError} If any interval has start > end.
 */
function validateIntervalList(intervals) {
  if (!Array.isArray(intervals)) {
    throw new TypeError('interval list must be an array');
  }

  for (const interval of intervals) {
    if (!Array.isArray(interval) || interval.length !== 2) {
      throw new TypeError('interval must be a two-element array');
    }

    const [start, end] = interval;
    assertSafeInteger(start);
    assertSafeInteger(end);

    if (start > end) {
      throw new RangeError('interval start must not exceed end');
    }
  }
}

/**
 * Normalises a list of intervals: drops empties, sorts, and coalesces
 * overlapping or touching intervals.
 * @param {unknown} intervals Interval list.
 * @returns {Array<[number, number]>} Normalised list.
 */
export function normalize(intervals) {
  // Validate input
  validateIntervalList(intervals);

  // Handle empty input
  if (intervals.length === 0) {
    return [];
  }

  // Filter out empty intervals and create copies
  const filtered = intervals
    .filter(interval => interval[0] < interval[1])
    .map(interval => [interval[0], interval[1]]);

  // If all intervals were empty, return empty array
  if (filtered.length === 0) {
    return [];
  }

  // Sort by start value
  filtered.sort((a, b) => a[0] - b[0]);

  // Coalesce overlapping or touching intervals
  const result = [filtered[0]];

  for (let i = 1; i < filtered.length; i++) {
    const current = filtered[i];
    const last = result[result.length - 1];

    // If current interval overlaps or touches the last one in result, merge them
    if (current[0] <= last[1]) {
      last[1] = Math.max(last[1], current[1]);
    } else {
      // No overlap/touch, add as new interval
      result.push([current[0], current[1]]);
    }
  }

  return result;
}

/**
 * Union of two interval lists.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised union.
 */
export function merge(a, b) {
  // Validate inputs
  validateIntervalList(a);
  validateIntervalList(b);

  // Combine both lists and normalize
  const combined = [...a, ...b];
  return normalize(combined);
}

/**
 * Intersection of two interval lists. Touching intervals do not intersect.
 * @param {unknown} a First interval list.
 * @param {unknown} b Second interval list.
 * @returns {Array<[number, number]>} Normalised intersection.
 */
export function intersect(a, b) {
  // Validate inputs
  validateIntervalList(a);
  validateIntervalList(b);

  // Normalize both lists first
  const normA = normalize(a);
  const normB = normalize(b);

  if (normA.length === 0 || normB.length === 0) {
    return [];
  }

  const result = [];
  let i = 0;
  let j = 0;

  while (i < normA.length && j < normB.length) {
    const [aStart, aEnd] = normA[i];
    const [bStart, bEnd] = normB[j];

    // Calculate intersection
    const start = Math.max(aStart, bStart);
    const end = Math.min(aEnd, bEnd);

    // Only add if there's actual overlap (start < end, not just touching)
    if (start < end) {
      result.push([start, end]);
    }

    // Move pointer for the interval that ends first
    if (aEnd < bEnd) {
      i++;
    } else if (bEnd < aEnd) {
      j++;
    } else {
      // Equal ends, move both
      i++;
      j++;
    }
  }

  return result;
}

/**
 * Relative complement `a \ b`.
 * @param {unknown} a Interval list to subtract from.
 * @param {unknown} b Interval list to remove.
 * @returns {Array<[number, number]>} Normalised difference.
 */
export function subtract(a, b) {
  // Validate inputs
  validateIntervalList(a);
  validateIntervalList(b);

  // Normalize both lists first
  const normA = normalize(a);
  const normB = normalize(b);

  if (normA.length === 0) {
    return [];
  }

  if (normB.length === 0) {
    return normA.map(interval => [interval[0], interval[1]]);
  }

  const result = [];

  for (const [aStart, aEnd] of normA) {
    let currentStart = aStart;

    for (const [bStart, bEnd] of normB) {
      // Skip b intervals that end before our current start
      if (bEnd <= currentStart) {
        continue;
      }

      // If b interval starts after our current end, we're done
      if (bStart >= aEnd) {
        break;
      }

      // If b interval starts after our current start, add the gap
      if (bStart > currentStart) {
        result.push([currentStart, Math.min(bStart, aEnd)]);
      }

      // Move currentStart past the b interval
      currentStart = Math.max(currentStart, bEnd);

      // If we've consumed the entire a interval, break
      if (currentStart >= aEnd) {
        break;
      }
    }

    // Add any remaining part of the a interval
    if (currentStart < aEnd) {
      result.push([currentStart, aEnd]);
    }
  }

  return result;
}

/**
 * Total length covered by a list of intervals, counting overlaps once.
 * @param {unknown} intervals Interval list.
 * @returns {number} Number of integers covered.
 */
export function coverage(intervals) {
  // Validate input
  validateIntervalList(intervals);

  // Normalize and sum up lengths
  const normalized = normalize(intervals);

  let total = 0;
  for (const [start, end] of normalized) {
    total += end - start;
  }

  return total;
}"}

