 * Glob patterns compiled to path matchers: wildcards that stop at `/`,
 * whole-segment globstars, POSIX-style character classes, backslash escapes and
 * the leading-dot rule.
 */

/** Failure raised while compiling a pattern. */
export class GlobError extends Error {
  /**
   * @param {string} message reason, without positional information
   * @param {number} [index] 0-based index into the pattern where the fault starts
   */
  constructor(message, index) {
    super(message);
    this.name = 'GlobError';
    this.index = index;
  }
}

/**
 * Parse one (non-globstar) pattern segment into a regex fragment plus metadata.
 *
 * @param {string} seg raw, unescaped segment text
 * @param {{ nocase: boolean }} opts case policy
 * @returns {{ body: string, dot: boolean }} `body` is the regex fragment (no
 *   anchors), `dot` is true when the segment begins with a literal dot so it is
 *   allowed to match a leading dot on a path segment.
 */
function parseSegment(seg, opts) {
  let body = '';
  let dot = false;
  let i = 0;
  const n = seg.length;
  while (i < n) {
    const ch = seg[i];
    if (ch === '\\') {
      // Backslash escapes the next character. A trailing backslash is an error,
      // but that is reported by the segment splitter using the pattern index.
      if (i + 1 >= n) {
        throw new GlobError('trailing backslash', -1);
      }
      const next = seg[i + 1];
      if (next === '.') {
        // Escaped dot: literal dot and, when first, allows a leading dot.
        if (body === '' && !dot) dot = true;
        body += '\\.';
      } else if (next === '/') {
        // Escaped separator: treat as a literal slash character within the
        // segment regex (it will never occur because the splitter consumes `/`
        // as a separator, but keep the rule consistent).
        body += '/';
      } else {
        body += escapeRegexChar(next);
      }
      i += 2;
      continue;
    }
    if (ch === '*') {
      // Collapse a run of stars into a single wildcard.
      while (i < n && seg[i] === '*') i += 1;
      body += '[^/]*';
      continue;
    }
    if (ch === '?') {
      body += '[^/]';
      i += 1;
      continue;
    }
    if (ch === '[') {
      const result = parseClass(seg, i, opts);
      body += result.body;
      i = result.next;
      continue;
    }
    body += escapeRegexChar(ch);
    i += 1;
  }
  // An unescaped leading dot also permits a leading-dot segment to match.
  if (!dot && body.startsWith('\\.')) {
    dot = true;
  }
  return { body, dot };
}

/**
 * Append the regex for a glob character class `[...]` starting at `i` (the `[`).
 *
 * @param {string} seg segment being parsed
 * @param {number} i index of the opening `[`
 * @param {{ nocase: boolean }} opts case policy
 * @returns {{ body: string, next: number }}
 */
function parseClass(seg, i, opts) {
  const start = i;
  const n = seg.length;
  // The opening bracket is consumed.
  i += 1;
  let negated = false;
  let body = '[';
  if (i < n && (seg[i] === '!' || seg[i] === '^')) {
    negated = true;
    body += '^';
    i += 1;
  }
  // A `]` immediately after the opening bracket (or negation mark) is literal.
  let first = true;
  let foundClose = false;
  while (i < n) {
    const ch = seg[i];
    if (ch === '\\') {
      if (i + 1 >= n) {
        // Handled by the segment splitter; never reached here.
        throw new GlobError('trailing backslash', -1);
      }
      body += escapeRegexChar(seg[i + 1]);
      i += 2;
      first = false;
      continue;
    }
    if (ch === '/' ) {
      throw new GlobError('path separator in character class', start);
    }
    if (ch === ']' && !first) {
      body += ']';
      i += 1;
      foundClose = true;
      break;
    }
    if (ch === ']') {
      // Literal `]` as the first character of the class.
      body += '\\]';
      i += 1;
      first = false;
      continue;
    }
    // Range handling: a `-` that closes a range is literal when at the edges.
    if (ch === '-' && (i === start + 1 || first)) {
      // Leading dash is literal; keep scanning for the real list.
      body += '\\-';
      i += 1;
      first = false;
      continue;
    }
    if (ch === '-' && i + 1 < n && seg[i + 1] !== ']') {
      // Could start a range. Peek: if the char after `-` and the char after
      // that form a range, emit a range; otherwise a literal dash.
      const lo = seg[i - 1];
      const hi = seg[i + 1];
      if (isRangeChar(lo) && isRangeChar(hi)) {
        body += rangeFrom(lo, hi, opts);
        i += 2;
        first = false;
        continue;
      }
      body += escapeRegexChar('-');
      i += 1;
      first = false;
      continue;
    }
    body += escapeRegexChar(ch);
    i += 1;
    first = false;
  }
  if (!foundClose) {
    throw new GlobError('unterminated character class', start);
  }
  body += ')';
  return { body, next: i };
}

/** @returns {true} for chars that can serve as a range endpoint */
function isRangeChar(ch) {
  return ch !== '' && ch !== ']' && ch !== '\\';
}

/** @returns regex range text for a literal range `lo`-`hi` */
function rangeFrom(lo, hi, opts) {
  if (opts.nocase) {
    // Emit a case-insensitive range covering both cases.
    return `(?:${rangeLiteral(lo)}|${rangeLiteral(hi)}|[${lo}${upper(lo)}-${upper(hi)}${lower(hi)}])`;
  }
  let text = `[${lo}-${hi}]`;
  return text;
}

/** @returns the upper-case form of an ASCII letter, or the char unchanged */
function upper(ch) {
  const c = ch.charCodeAt(0);
  if (c >= 97 && c <= 122) return String.fromCharCode(c - 32);
  return ch;
}

/** @returns the lower-case form of an ASCII letter, or the char unchanged */
function lower(ch) {
  const c = ch.charCodeAt(0);
  if (c >= 65 && c <= 90) return String.fromCharCode(c + 32);
  return ch;
}

/** @returns true when this character should appear as itself inside `[...]` */
function classLiteral(ch) {
  if (ch === '/' ) return false;
  return ch;
}

/**
 * Escape a character for use as a literal inside a regex character class.
 * Only the characters that are special inside `[...]` need escaping.
 */
function escapeClassChar(ch) {
  if (ch === '\\' || ch === ']' || ch === '-' || ch === '^') {
    return '\\' + ch;
  }
  return ch;
}

/**
 * Escape a single literal character for use in a regex (outside a class).
 * Re-special characters are escaped; others pass through.
 */
function escapeRegexChar(ch) {
  if ('\\^$.|?*+()[]{}'.indexOf(ch) !== -1) {
    return '\\' + ch;
  }
  return ch;
}

/**
 * Compile a glob `pattern` (split into its `/`-separated segments) into a
 * sequence of regex fragments, one per segment, plus segment metadata.
 *
 * Adjacent globstar segments are collapsed, and a `**` that is a whole segment
 * is recorded with `globstar: true` so the matcher can consume zero or more
 * segments.
 *
 * @param {string} pattern
 * @param {{ nocase: boolean }} opts
 * @returns {Array<{ regex: string, dot: boolean, globstar: boolean, index: number }>}
 */
function compileSegments(pattern, opts) {
  const segments = [];
  const push = (seg, index) => {
    if (seg.length === 2 && seg[0] === '*' && seg[1] === '*') {
      segments.push({ regex: null, dot: false, globstar: true, index });
      return;
    }
    const parsed = parseSegment(seg, opts);
    segments.push({ regex: parsed.body, dot: parsed.dot, globstar: false, index });
  };

  let current = '';
  let i = 0;
  const n = pattern.length;
  while (i < n) {
    const ch = pattern[i];
